function SignedTradeRecordActions({transaction}) {
 const [docs,setDocs]=useState([]),[open,setOpen]=useState(false),[selected,setSelected]=useState(null),[previewUrl,setPreviewUrl]=useState(""),[message,setMessage]=useState("");
 useEffect(()=>{let live=true;(async()=>{if(!supabase||!transaction?.id){setDocs([]);return}const {data,error}=await supabase.from("dv_accounting_transaction_documents").select("*").eq("transaction_id",transaction.id).eq("document_type","SIGNED_TRADE_RECORD").order("created_at",{ascending:false});if(live)setDocs(error?[]:(data||[]))})();return()=>{live=false}},[transaction?.id]);
 async function preview(doc){if(!doc)return;const {data,error}=await supabase.storage.from("dv-trade-documents").createSignedUrl(doc.storage_path,900);if(error){setMessage("Could not preview signed trade record: "+error.message);return}setSelected(doc);setPreviewUrl(data.signedUrl);setMessage("")}
 async function download(doc){if(!doc)return;const {data,error}=await supabase.storage.from("dv-trade-documents").createSignedUrl(doc.storage_path,300,{download:doc.document_name||true});if(error){setMessage("Could not download signed trade record: "+error.message);return}const link=document.createElement("a");link.href=data.signedUrl;link.target="_blank";link.rel="noopener noreferrer";link.click()}
 if(!docs.length)return null;
 return <>
  <button type="button" className="textbutton" onClick={e=>{e.preventDefault();e.stopPropagation();setOpen(true);setSelected(docs[0]);preview(docs[0])}}>Signed Trade Record: Preview / Print / Save</button>
  {open&&<div className="overlay" style={{zIndex:1200}} onClick={e=>{if(e.target===e.currentTarget)setOpen(false)}}>
   <div className="modal tx-modal" style={{maxWidth:1000,width:"min(1000px,96vw)",maxHeight:"92vh",overflow:"auto"}} onClick={e=>e.stopPropagation()}>
    <div className="paneltitle"><div><h2>Signed Trade Record</h2><p className="panelhint">{transaction.transaction_number||"Transaction"} · {transaction.property_address||[transaction.street_number,transaction.street_name].filter(Boolean).join(" ")}</p></div><button type="button" className="secondary" onClick={()=>setOpen(false)}>Close</button></div>
    <label>Attached signed trade record<select value={selected?.id||""} onChange={e=>{const doc=docs.find(d=>d.id===e.target.value);setSelected(doc||null);setPreviewUrl("");if(doc)preview(doc)}} style={{display:"block",width:"100%",marginTop:5}}>{docs.map(doc=><option key={doc.id} value={doc.id}>{doc.document_name} · {doc.created_at?new Date(doc.created_at).toLocaleDateString():""}</option>)}</select></label>
    {message&&<div className="error">{message}</div>}
    {selected&&<div className="actions" style={{margin:"10px 0",display:"flex",gap:8,flexWrap:"wrap"}}><button type="button" className="secondary" onClick={()=>preview(selected)}>Preview</button><button type="button" className="secondary" disabled={!previewUrl} onClick={()=>{const w=window.open(previewUrl,"_blank","noopener,noreferrer");if(!w)setMessage("Allow pop-ups to open the PDF, then use its Print or Save controls.")}}>Open / Print / Save PDF</button><button type="button" className="secondary" onClick={()=>download(selected)}>Download PDF</button></div>}
    {previewUrl&&<iframe title="Signed trade record preview" src={previewUrl} style={{width:"100%",height:"min(65vh,650px)",border:"1px solid #d0d5dd",borderRadius:8,background:"#fff"}}/>}
   </div>
  </div>}
 </>
}

