 const arAlreadyRecorded=!!tx.ar_payment_received&&Number(tx.ar_payment_amount||0)>0&&!!tx.ar_payment_bank_account_id; if(!confirm(sellerWorkflow?"Create or refresh the Commission Payroll record using Dream Valley's own listing commission only? Seller payment and the Commission Trust transfer must already be complete.":arAlreadyRecorded?"Send this closed transaction back to Commission Payroll for review? The commission AR receipt is already recorded for "+money(Number(tx.ar_payment_amount||0))+" on "+(tx.ar_payment_received_date||"the recorded date")+". This action will not request or create another receipt.":"Send this closed transaction back to Commission Payroll? The returned commission will be marked ready for review. Payment remains blocked until the full commission AR receipt is recorded."))return;
