   const gross=Math.round(ownRows.reduce((sum,x)=>sum+Number(x.amount||0),0)*100)/100;
   if(gross<=0)throw new Error("Dream Valley's own "+ownSide.toLowerCase()+" commission is still $0. Open the transaction, correct the commission line, save it, and retry.");
   const calc=await supabase.rpc("dv_accounting_calculate_commission_fees",{p_agent_id:agentInfo.agent_id,p_transaction_id:tx.id,p_gross_commission:gross,p_as_of:transaction.close_date||transaction.firm_date||today()});
   if(calc.error)throw calc.error;
